// Structure to hold the return values
typedef struct {
    unsigned char* encrypted_data;
    size_t encrypted_len;
    unsigned char* iv;
    unsigned char* key;
} encryption_result;

/**
Encrypt the data with the key using CBC mode.
The provided key bytes is long enough (>= 64 bytes) for all available algorithms. Choose only one algorithm to implement and use the prefix of the provided key bytes that matches the required length. Do NOT choose the algorithm based on the length of the key.
Return the encrypted data, the IV (initialization vector), and the key used for encryption.

@param key The bytes to generate the encryption key.
@param data The data to encrypt.

@return The encrypted data, the IV, and the key used for encryption.
*/
encryption_result encrypt_data(
    const unsigned char* key, size_t key_len,
    const unsigned char* data, size_t data_len
) {
    // BEGIN SOLUTION
    encryption_result result = {NULL, 0, NULL, NULL};

    // Validate input parameters
    if (!key || !data || key_len < 16) {
        return result;
    }

    // Allocate memory for IV and key
    result.iv = (unsigned char*)malloc(AES_BLOCK_SIZE);
    result.key = (unsigned char*)malloc(16);  // AES-128 key size
    if (!result.iv || !result.key) {
        free(result.iv);
        free(result.key);
        return result;
    }

    // Generate random IV
    if (RAND_bytes(result.iv, AES_BLOCK_SIZE) != 1) {
        free(result.iv);
        free(result.key);
        return result;
    }

    // Copy first 16 bytes of key
    memcpy(result.key, key, 16);

    // Pad the input data
    size_t padded_len;
    unsigned char* padded_data = pad_data(data, data_len, &padded_len);
    if (!padded_data) {
        free(result.iv);
        free(result.key);
        return result;
    }

    // Allocate memory for encrypted data
    result.encrypted_data = (unsigned char*)malloc(padded_len);
    if (!result.encrypted_data) {
        free(result.iv);
        free(result.key);
        free(padded_data);
        return result;
    }
    result.encrypted_len = padded_len;

    // Initialize AES encryption
    AES_KEY aes_key;
    if (AES_set_encrypt_key(result.key, 128, &aes_key) != 0) {
