            type_index = i;
            break;
        }
    }

    if (type_index == -1) {
        // info_type is invalid
        return;
    }

    std::string sanitized_content = info_content;
    sanitize_input(sanitized_content);

    header[header_keys[type_index]] = sanitized_content;
}

